CREATE ROLE anon;CREATE ROLE authenticated;
CREATE SCHEMA lts_product_refresh_private_v415;
CREATE TABLE lts_product_refresh_private_v415.queue(user_id uuid PRIMARY KEY,state text);
INSERT INTO lts_product_refresh_private_v415.queue VALUES('00000000-0000-4000-8000-000000000001','ready');
CREATE TABLE lts_read_cache_epoch_v242(singleton boolean PRIMARY KEY,epoch bigint);INSERT INTO lts_read_cache_epoch_v242 VALUES(true,1);
CREATE TABLE lts_v229_read_cache(user_id uuid,kind text,as_of date,from_date date,to_date date,payload jsonb,refreshed_at timestamptz,source_fingerprint text,PRIMARY KEY(user_id,kind,as_of,from_date,to_date));
CREATE TABLE fixture_expenses(user_id uuid,row_key text,event_date date,transaction_date date,competence_month date,amount numeric,category text,beneficiary text,description text,account_source text,source_table text,source_ref text,coverage_mode text,raw_category text,raw_reference text,purchase_date date,identity_status text,management_group text,management_subgroup text,property_code text,property_component text,cost_center text);
CREATE FUNCTION lts_v229_expense_rows(p_user_id uuid,p_from date,p_to date) RETURNS TABLE(row_key text,event_date date,transaction_date date,competence_month date,amount numeric,category text,beneficiary text,description text,account_source text,source_table text,source_ref text,coverage_mode text,raw_category text,raw_reference text,purchase_date date,identity_status text,management_group text,management_subgroup text,property_code text,property_component text) LANGUAGE sql STABLE SET search_path TO 'public' AS $$SELECT row_key,event_date,transaction_date,competence_month,amount,category,beneficiary,description,account_source,source_table,source_ref,coverage_mode,raw_category,raw_reference,purchase_date,identity_status,management_group,management_subgroup,property_code,property_component FROM fixture_expenses WHERE user_id=p_user_id AND event_date BETWEEN p_from AND p_to$$;
CREATE FUNCTION lts_expense_effective_rows_v176(p_user_id uuid,p_from date,p_to date) RETURNS TABLE(source_table text,source_ref text,center_cost text) LANGUAGE sql STABLE SET search_path TO 'public' AS $$SELECT source_table,source_ref,cost_center FROM fixture_expenses WHERE user_id=p_user_id AND event_date BETWEEN p_from AND p_to$$;
CREATE FUNCTION lts_browser_assert_user_v1() RETURNS uuid LANGUAGE sql STABLE SET search_path TO 'public' AS $$SELECT coalesce(nullif(current_setting('lts_test.user',true),''),'00000000-0000-4000-8000-000000000001')::uuid$$;
CREATE FUNCTION lts_card_read_start_v269(uuid) RETURNS text LANGUAGE sql STABLE SET search_path TO 'public' AS $$SELECT 'synthetic-revision'::text$$;
CREATE FUNCTION lts_card_read_finish_v269(uuid,text,jsonb) RETURNS jsonb LANGUAGE sql STABLE SET search_path TO 'public' AS $$SELECT $3$$;
CREATE FUNCTION lts_v178_norm(text) RETURNS text LANGUAGE sql IMMUTABLE AS $$SELECT lower($1)$$;
CREATE FUNCTION lts_card_family_v226(text,text) RETURNS text LANGUAGE sql IMMUTABLE AS $$SELECT null::text$$;
CREATE TABLE lts_open_finance_staging(user_id uuid,id uuid,normalized_payload jsonb,institution_name text);
CREATE TABLE lts_card_history_source_audit_v235(user_id uuid,source_table text,source_ref text,event_date date,source_signed_amount numeric,source_file text,source_sheet text,source_rows jsonb,composition_status text,detail_rows bigint,detail_total numeric,detail_difference numeric);
CREATE TABLE lts_workbook_identity_evidence_v232(user_id uuid,source_table text,source_ref text,original_category text,original_description text,source_sheet text,source_rows jsonb);
CREATE TABLE lts_card_history_item_v346(user_id uuid,parent_key text,amount numeric);
CREATE TABLE lts_card_history_parent_v346(user_id uuid,parent_key text,signature text);
CREATE FUNCTION lts_card_history_signature_v346(jsonb) RETURNS text LANGUAGE sql IMMUTABLE AS $$SELECT md5($1::text)$$;
CREATE FUNCTION lts_card_history_status_v346(boolean,boolean,numeric,numeric,bigint) RETURNS text LANGUAGE sql IMMUTABLE AS $$SELECT 'synthetic-fixture'::text$$;
CREATE FUNCTION lts_browser_expenses_v229_engine_v251(p_from date,p_to date) RETURNS jsonb LANGUAGE sql STABLE SET search_path TO 'public' AS $$SELECT jsonb_build_object('summary',jsonb_build_object('selected_total',sum(amount),'card_total',sum(amount) FILTER(WHERE source_table LIKE '%card%' OR coverage_mode LIKE 'card_%'),'account_total',sum(amount) FILTER(WHERE NOT(source_table LIKE '%card%' OR coverage_mode LIKE 'card_%')),'rows',count(*))) FROM lts_v229_expense_rows(lts_browser_assert_user_v1(),p_from,p_to)$$;
